  root(c,"useFireWeaponSpell","nativeSourceFireWeaponOriginalBody","fire","FireWeaponSpell");root(c,"useWindShotSpell","nativeSourceWindShotOriginalBody","wind","WindShotSpell");var frame=method(c,"nativeStaticOriginalFrame");var p=new InsnList();p.add(new VarInsnNode(ALOAD,0));p.add(new VarInsnNode(ALOAD,1));p.add(new MethodInsnNode(INVOKESTATIC,N,"allowFrame","(L"+PC+";[B)Z",false));var allowed=new LabelNode();p.add(new JumpInsnNode(IFNE,allowed));p.add(new InsnNode(RETURN));p.add(allowed);p.add(new FrameNode(F_NEW,3,new Object[]{PC,"[B","java/lang/String"},0,null));frame.instructions.insert(p);
